// Junta el uso de Armoni de cada celular de la casa. Quién es se sabe por Tailscale (la cuenta que abrió la app);
// si no llega, se usa el código que la app guarda en ese celular. Solo se guardan conteos: apartado, visitas y segundos.
const it = $input.first().json;
let b = it.body;
if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = {}; } }
b = b || {};
if (b.token !== 'mercado-7d41c2a9e05b') return [{ json: { ok: false, error: 'token' } }];
const h = it.headers || {};
const login = String(h['tailscale-user-login'] || '').trim().toLowerCase();
const quien = (login ? login.split('@')[0] : String(b.equipo || 'celular')).replace(/[^a-z0-9._-]/gi, '').slice(0, 40) || 'celular';
const sd = $getWorkflowStaticData('global');
sd.equipos = sd.equipos || {};
if (b.dias && typeof b.dias === 'object') {
  const corte = new Date(Date.now() - 90 * 864e5).toISOString().slice(0, 10);
  const dias = {};
  for (const [dia, ms] of Object.entries(b.dias)) {
    if (!/^\d{4}-\d{2}-\d{2}$/.test(dia) || dia < corte || !ms || typeof ms !== 'object') continue;
    const d = {};
    for (const [k, m] of Object.entries(ms).slice(0, 60)) {
      if (!m || typeof m !== 'object') continue;
      d[String(k).slice(0, 30)] = { v: Math.max(0, Math.min(1e5, Number(m.v) || 0)), s: Math.max(0, Math.min(1e7, Number(m.s) || 0)) };
    }
    dias[dia] = d;
  }
  sd.equipos[quien] = { dias, visto: new Date().toISOString() };
}
return [{ json: { ok: true, yo: quien, equipos: sd.equipos } }];
